import { createContext, useContext, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Link, Navigate, Route, Routes, useLocation, useParams } from "react-router-dom";
import { components as initialComponents, githubPullRequests, releases as initialReleases, repositoryReadmes, teams as initialTeams } from "./data";
import { id, type ApprovalStatus, type Component, type ComponentChange, type ComponentKind, type GitHubPullRequest, type PlanCandidate, type Release, type ReleaseStatus, type RepositoryReadme, type RunbookStep, type Team, type VersionTransition } from "./domain";

type Store = {
  teams: Team[]; components: Component[]; releases: Release[];
  setTeams: React.Dispatch<React.SetStateAction<Team[]>>;
  setComponents: React.Dispatch<React.SetStateAction<Component[]>>;
  setReleases: React.Dispatch<React.SetStateAction<Release[]>>;
};
const DataContext = createContext<Store | null>(null);
const useData = () => useContext(DataContext)!;
const statusText: Record<ReleaseStatus, string> = { draft: "下書き", preparing: "準備中", ready: "実行可能", running: "実行中", completed: "完了" };

function useStored<T>(key: string, seed: T) {
  const [value, setValue] = useState<T>(() => { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : seed; } catch { return seed; } });
  useEffect(() => localStorage.setItem(key, JSON.stringify(value)), [key, value]);
  return [value, setValue] as const;
}

export default function App() {
  const [teams, setTeams] = useStored("relay-teams", initialTeams);
  const [components, setComponents] = useStored("relay-components", initialComponents);
  const [releases, setReleases] = useStored("relay-releases", initialReleases);
  return <DataContext.Provider value={{ teams, components, releases, setTeams, setComponents, setReleases }}><Layout /></DataContext.Provider>;
}

function Layout() {
  const location = useLocation(); const section = location.pathname.split("/")[1] || "releases";
  const [theme, setTheme] = useState(localStorage.getItem("relay-theme") ?? "dark"); document.documentElement.dataset.theme = theme;
  const toggleTheme = () => { const next = theme === "dark" ? "light" : "dark"; setTheme(next); localStorage.setItem("relay-theme", next); };
  return <main className="shell"><aside className="rail"><Link className="brand" to="/releases"><Logo /><span>Relay</span></Link><nav className="nav"><Nav to="/releases" active={section === "releases"}>リリース</Nav><Nav to="/teams" active={section === "teams"}>チーム</Nav><Nav to="/components" active={section === "components"}>コンポーネント</Nav></nav><div className="rail-bottom"><div className="jef-presence"><span className="pulse" />Jev 判定を利用可能</div><div className="account"><span>TK</span><span>Taross K.</span></div></div></aside><section className="workspace"><Header theme={theme} toggle={toggleTheme} /><Routes><Route path="/" element={<Navigate to="/releases" replace />} /><Route path="/releases" element={<ReleaseList />} /><Route path="/releases/:releaseId" element={<ReleaseRedirect />} /><Route path="/releases/:releaseId/:tab" element={<ReleaseDetail />} /><Route path="/teams" element={<TeamList />} /><Route path="/components" element={<ComponentList />} /><Route path="*" element={<NotFound />} /></Routes></section></main>;
}

function Logo() { return <svg viewBox="0 0 24 24"><path d="M4 4h8v8H4zM12 12h8v8h-8zM12 4h8v8" /></svg>; }
function Nav({ to, active, children }: { to: string; active: boolean; children: ReactNode }) { return <Link to={to} className={`nav-item ${active ? "active" : ""}`}>{children}</Link>; }
function Header({ theme, toggle }: { theme: string; toggle: () => void }) { const { releases } = useData(); const [showJev, setShowJev] = useState(false); const parts = useLocation().pathname.split("/"); const section = parts[1]; const release = section === "releases" ? releases.find((item) => item.id === parts[2]) : undefined; const title = release?.name ?? (section === "teams" ? "チーム" : section === "components" ? "コンポーネント" : "リリース"); return <><header className="topbar"><div><span className="eyebrow">{release?.code ?? (section === "teams" ? "組織" : section === "components" ? "プロダクト" : "リリース管理")}</span><div className="release-title">{title}</div></div><div className="top-actions"><button className="theme-toggle" onClick={toggle}>{theme === "dark" ? "ライト" : "ダーク"}</button>{release && <><Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画</Link><button className="primary" onClick={() => setShowJev(true)}>Jevリスク判定デモ</button></>}</div></header>{showJev && release && <JevRiskDemo release={release} close={() => setShowJev(false)} />}</>; }

function ReleaseList() {
  const data = useData(); const [editing, setEditing] = useState<Release | "new" | null>(null);
  const remove = (release: Release) => confirm(`${release.code}を削除しますか？`) && data.setReleases((items) => items.filter((item) => item.id !== release.id));
  return <section className="collection-view"><CollectionHeader count={data.releases.length} title="リリース" action="リリースを作成" onAction={() => setEditing("new")} /><div className="release-list-head"><span>リリース</span><span>予定日</span><span>責任チーム</span><span>変更</span><span>状態</span><span /></div>{data.releases.map((release) => { const changes = getChanges(release); const names = [...new Set(changes.map((change) => component(data, change.componentId)?.name ?? "削除済み"))]; return <div className="release-list-row" key={release.id}><Link className="release-name" to={`/releases/${release.id}/changes`}><small>{release.code}</small><b>{release.name}</b><em>{names.join("、") || "対象コンポーネント未設定"}</em></Link><span>{dateText(release.scheduledFor)}</span><span>{team(data, release.ownerTeamId)?.name}</span><span>{changes.length}件</span><span className={`release-status ${release.status}`}>{statusText[release.status]}</span><Actions edit={() => setEditing(release)} remove={() => remove(release)} /></div>; })}{editing && <ReleaseForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>;
}

function ReleaseForm({ target, close }: { target?: Release; close: () => void }) {
  const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const next: Release = target ? { ...target, code: str(f, "code"), name: str(f, "name"), scheduledFor: str(f, "date"), ownerTeamId: id(str(f, "team")), status: str(f, "status") as ReleaseStatus } : { id: id(crypto.randomUUID()), code: str(f, "code"), name: str(f, "name"), scheduledFor: str(f, "date"), ownerTeamId: id(str(f, "team")), status: "draft", featureChanges: [], verifications: [] }; data.setReleases((items) => target ? items.map((item) => item.id === target.id ? next : item) : [next, ...items]); close(); };
  return <Dialog title={target ? "リリースを編集" : "リリースを作成"} close={close}><form onSubmit={save}><Input label="リリースID" name="code" value={target?.code} /><Input label="名称" name="name" value={target?.name} /><Input label="予定日" name="date" type="date" value={target?.scheduledFor} /><Choice label="責任チーム" name="team" value={target?.ownerTeamId} options={data.teams.map((item) => [item.id, item.name])} />{target && <Choice label="状態" name="status" value={target.status} options={Object.entries(statusText)} />}<Save /></form></Dialog>;
}

function ReleaseRedirect() { const { releaseId } = useParams(); return <Navigate to={`/releases/${releaseId}/changes`} replace />; }
function ReleaseDetail() { const data = useData(); const { releaseId, tab = "changes" } = useParams(); const release = data.releases.find((item) => item.id === releaseId); if (!release) return <NotFound />; const activeTab = ["changes", "dependencies", "plan", "runbook", "verification", "approval"].includes(tab) ? tab : "changes"; return <><div className="release-context"><Link to="/releases">← リリース一覧</Link><span>{dateTimeText(release.scheduledAt ?? `${release.scheduledFor}T10:00`)}</span><span>{team(data, release.ownerTeamId)?.name}</span><span className={`release-status ${release.status}`}>{statusText[release.status]}</span></div><nav className="release-tabs"><Tab release={release} name="changes" active={activeTab}>変更</Tab><Tab release={release} name="dependencies" active={activeTab}>依存マップ</Tab><Tab release={release} name="plan" active={activeTab}>実行計画</Tab><Tab release={release} name="runbook" active={activeTab}>手順書</Tab><Tab release={release} name="verification" active={activeTab}>検証</Tab><Tab release={release} name="approval" active={activeTab}>承認・予定</Tab></nav>{activeTab === "changes" ? <Changes release={release} /> : activeTab === "dependencies" ? <DependencyMap release={release} /> : activeTab === "plan" ? <Plan release={release} /> : activeTab === "runbook" ? <Runbook release={release} /> : activeTab === "verification" ? <Verifications release={release} /> : <ApprovalSchedule release={release} />}</>; }
function Tab({ release, name, active, children }: { release: Release; name: string; active: string; children: ReactNode }) { return <Link className={active === name ? "active" : ""} to={`/releases/${release.id}/${name}`}>{children}</Link>; }

function Changes({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const groups = groupChanges(data, changes); const [activeId, setActiveId] = useState(changes[0]?.id ?? ""); const [editing, setEditing] = useState<ComponentChange | "new" | null>(null); const [planning, setPlanning] = useState<ComponentChangeGroup | null>(null); const [importing, setImporting] = useState(false); const active = changes.find((item) => item.id === activeId) ?? changes[0];
  const remove = (change: ComponentChange) => { if (!confirm("このコンポーネント変更を削除しますか？")) return; updateRelease(data, release.id, (current) => invalidatePlan({ ...current, featureChanges: current.featureChanges.map((feature) => ({ ...feature, componentChanges: feature.componentChanges.filter((item) => item.id !== change.id) })), verifications: current.verifications.filter((item) => item.componentChangeId !== change.id) }, "コンポーネント変更が削除されました")); };
  return <div className="release-layout"><section className="release-main"><div className="view-head"><div><span className="eyebrow">{groups.length}コンポーネント · {changes.length}変更</span><h1>コンポーネント変更</h1></div><div className="view-actions"><button className="ghost" onClick={() => setImporting(true)}>GitHub PRから取り込む</button><button className="ghost" onClick={() => setEditing("new")}>＋ 変更を追加</button></div></div>{groups.map((group) => { const transition = versionTransition(group.changes[0], group.component, release); return <section className="component-change-group" key={group.component.id}><header><span className={`component-kind kind-${group.component.kind}`}>{group.component.name.slice(0, 1)}</span><div><h2>{group.component.name}</h2><small>{team(data, group.component.ownerTeamId)?.name} · {group.changes.length}変更</small></div><div className="group-version"><b>{transition.currentVersion} → {transition.targetVersion}</b><span>{rolloutText(transition.rollout)} · {coexistenceText(transition.coexistence)}</span><small>{versionSourceText(transition.versionSource)}</small><button onClick={() => setPlanning(group)}>バージョン計画を編集</button></div></header><div className="table-head"><span>変更内容</span><span>PR</span><span>migration</span><span>依存先</span><span>操作</span></div>{group.changes.map((change) => <div className={`release-row ${active?.id === change.id ? "selected" : ""}`} key={change.id} onClick={() => setActiveId(change.id)}><span className="change-cell"><span><b>{change.summary}</b><small>{change.pullRequests[0]?.repository}</small></span></span><span className="mono">#{change.pullRequests[0]?.number ?? "—"}</span><span>{change.migration.required ? change.migration.phase : "なし"}</span><span>{change.dependencyIds.length ? `${change.dependencyIds.length}件` : "なし"}</span><Actions edit={() => setEditing(change)} remove={() => remove(change)} /></div>)}</section>; })}</section>{active ? <ChangeDetail change={active} changes={changes} release={release} /> : <aside className="change-detail"><Empty text="変更がありません" /></aside>}{editing && <ChangeForm release={release} target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}{planning && <ComponentPlanForm release={release} group={planning} close={() => setPlanning(null)} />}{importing && <GitHubImport release={release} close={() => setImporting(false)} />}</div>;
}

function ChangeForm({ release, target, close }: { release: Release; target?: ComponentChange; close: () => void }) {
  const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const selected = data.components.find((item) => item.id === str(f, "component"))!; const next: ComponentChange = { id: target?.id ?? id(crypto.randomUUID()), componentId: selected.id, ownerTeamId: selected.ownerTeamId, summary: str(f, "summary"), pullRequests: [{ repository: selected.repository, number: Number(f.get("pr")), revision: str(f, "revision"), state: "review" }], migration: str(f, "migration") === "none" ? { required: false } : { required: true, phase: str(f, "migration") as "expand" | "migrate" | "contract", execution: str(f, "execution") as "online" | "blocking", backwardCompatible: str(f, "compatible") === "yes" }, maintenance: str(f, "maintenance") as ComponentChange["maintenance"], dependencyIds: Array.from(f.getAll("dependencies")).map((value) => id(String(value))), deploymentWindow: str(f, "window"), recovery: str(f, "recovery") }; updateRelease(data, release.id, (current) => { const features = current.featureChanges.length ? current.featureChanges : [{ id: id<"FeatureChange">("feature-default"), name: current.name, description: "", componentChanges: [] }]; return invalidatePlan({ ...current, featureChanges: features.map((feature, index) => index ? feature : { ...feature, componentChanges: target ? feature.componentChanges.map((item) => item.id === target.id ? next : item) : [...feature.componentChanges, next] }) }, "コンポーネント変更が更新されました"); }); close(); };
  const candidates = getChanges(release).filter((item) => item.id !== target?.id);
  return <Dialog title={target ? "コンポーネント変更を編集" : "コンポーネント変更を追加"} close={close}><form onSubmit={save}><Choice label="コンポーネント" name="component" value={target?.componentId} options={data.components.map((item) => [item.id, item.name])} /><Input label="変更内容" name="summary" value={target?.summary} /><Input label="PR番号" name="pr" type="number" value={String(target?.pullRequests[0]?.number ?? "")} /><Input label="revision" name="revision" value={target?.pullRequests[0]?.revision} /><Choice label="migration" name="migration" value={target?.migration.phase ?? "none"} options={[["none", "なし"], ["expand", "expand"], ["migrate", "migrate"], ["contract", "contract"]]} /><Choice label="実行方式" name="execution" value={target?.migration.execution ?? "online"} options={[["online", "online"], ["blocking", "blocking"]]} /><Choice label="後方互換" name="compatible" value={target?.migration.backwardCompatible ? "yes" : "no"} options={[["yes", "あり"], ["no", "なし"]]} /><Choice label="停止・メンテナンス" name="maintenance" value={target?.maintenance ?? "undetermined"} options={[["none", "不要"], ["maintenance-mode", "メンテナンスモード"], ["service-stop", "サービス停止"], ["undetermined", "未判定"]]} /><label>依存する変更<select name="dependencies" multiple defaultValue={target?.dependencyIds as string[]}>{candidates.map((item) => <option value={item.id} key={item.id}>{component(data, item.componentId)?.name} #{item.pullRequests[0]?.number}</option>)}</select></label><Input label="反映予定" name="window" value={target?.deploymentWindow} /><Input label="回復方法" name="recovery" value={target?.recovery} /><Save /></form></Dialog>;
}

function ComponentPlanForm({ release, group, close }: { release: Release; group: ComponentChangeGroup; close: () => void }) { const data = useData(); const current = versionTransition(group.changes[0], group.component, release); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const rollout = str(f, "rollout") as VersionTransition["rollout"]; const startsAt = str(f, "startsAt"); const expectedCompletionAt = str(f, "expectedCompletionAt"); updateRelease(data, release.id, (target) => invalidatePlan({ ...target, componentPlans: [...(target.componentPlans ?? []).filter((plan) => plan.componentId !== group.component.id), { componentId: group.component.id, currentVersion: str(f, "currentVersion"), targetVersion: str(f, "targetVersion"), versionSource: str(f, "versionSource") as VersionTransition["versionSource"], rollout, startsAt, expectedCompletionAt, coexistence: str(f, "coexistence") as VersionTransition["coexistence"], adoptionMilestones: rolloutMilestones(rollout, startsAt, expectedCompletionAt) }] }, `${group.component.name}のバージョン計画が変更されました`)); close(); }; const identifierLabel = ["backend", "admin"].includes(group.component.kind) ? "revision / artifact" : "アプリバージョン"; return <Dialog title={`${group.component.name}のバージョン計画`} close={close}><form onSubmit={save}><Input label={`現在の${identifierLabel}`} name="currentVersion" value={current.currentVersion} /><Input label={`変更後の${identifierLabel}`} name="targetVersion" value={current.targetVersion} /><Choice label="識別子の取得元" name="versionSource" value={current.versionSource ?? "manual"} options={[["deployment", "デプロイ環境"], ["github", "GitHub Actions artifact"], ["app-store", "App Store Connect"], ["google-play", "Google Play Console"], ["manual", "手入力"]]} /><Choice label="切替方式" name="rollout" value={current.rollout} options={[["immediate", "即時切替"], ["phased", "段階切替"], ["store-phased", "ストア段階配信"]]} /><Choice label="新旧バージョンの共存" name="coexistence" value={current.coexistence} options={[["compatible", "互換性あり"], ["feature-flag", "Feature Flagで制御"], ["incompatible", "共存不可"]]} /><Input label="切替開始" name="startsAt" type="datetime-local" value={current.startsAt} /><Input label="100%到達予定" name="expectedCompletionAt" type="datetime-local" value={current.expectedCompletionAt} /><Save /></form></Dialog>; }

function GitHubImport({ release, close }: { release: Release; close: () => void }) {
  const data = useData(); const changes = getChanges(release); const linked = data.components.filter((item) => item.githubConnection !== "disconnected" && item.repository); const [componentId, setComponentId] = useState<string>(linked[0]?.id ?? ""); const available = githubPullRequests.filter((item) => item.componentId === componentId); const [selectedNumber, setSelectedNumber] = useState<number | null>(available[0]?.number ?? null); const selected = githubPullRequests.find((item) => item.componentId === componentId && item.number === selectedNumber) ?? available[0];
  const chooseComponent = (value: string) => { setComponentId(value); setSelectedNumber(githubPullRequests.find((item) => item.componentId === value)?.number ?? null); };
  const imported = (pr: GitHubPullRequest) => changes.some((change) => change.pullRequests.some((item) => item.repository === pr.repository && item.number === pr.number));
  const add = () => { if (!selected || imported(selected)) return; const migrationRequired = selected.labels.some((label) => label.includes("migration")) || selected.changedFiles.some((file) => file.includes("migrations/")); const dependencyPr = selected.body.match(/#(\d+)/)?.[1]; const dependency = changes.find((change) => change.pullRequests.some((pr) => String(pr.number) === dependencyPr)); const next: ComponentChange = { id: id(crypto.randomUUID()), componentId: selected.componentId, ownerTeamId: component(data, selected.componentId)!.ownerTeamId, summary: selected.title, pullRequests: [{ repository: selected.repository, number: selected.number, revision: selected.revision, state: selected.state, title: selected.title, description: selected.body, author: selected.author, url: `https://github.com/${selected.repository}/pull/${selected.number}`, labels: selected.labels, changedFiles: selected.changedFiles, additions: selected.additions, deletions: selected.deletions }], migration: migrationRequired ? { required: true, phase: selected.labels.includes("expand-migration") ? "expand" : "migrate", execution: selected.labels.includes("blocking-migration") ? "blocking" : "online", backwardCompatible: !selected.labels.includes("breaking-change") } : { required: false }, maintenance: selected.labels.includes("blocking-migration") ? "undetermined" : "none", dependencyIds: dependency ? [dependency.id] : [], deploymentWindow: "未設定", recovery: `GitHub PR #${selected.number}をrevertし、直前revisionへ戻す` }; updateRelease(data, release.id, (current) => invalidatePlan({ ...current, featureChanges: current.featureChanges.map((feature, index) => index === 0 ? { ...feature, componentChanges: [...feature.componentChanges, next] } : feature) }, `GitHub PR #${selected.number}が追加されました`)); close(); };
  const migrationDetected = selected && (selected.labels.some((label) => label.includes("migration")) || selected.changedFiles.some((file) => file.includes("migrations/")));
  return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal github-import"><button className="panel-close" onClick={close}>×</button><header className="import-heading"><span className="demo-badge">GitHubモック · API未接続</span><h2>PRから変更を取り込む</h2><p>コンポーネントに紐付いたリポジトリのPRから、リリース変更の初期値を生成します。</p></header><label className="repo-filter">コンポーネント<select value={componentId} onChange={(event) => chooseComponent(event.target.value)}>{linked.map((item) => <option value={item.id} key={item.id}>{item.name} · {item.repository}</option>)}</select></label><div className="pr-import-layout"><div className="pr-list">{available.map((pr) => <button className={selected?.number === pr.number ? "selected" : ""} onClick={() => setSelectedNumber(pr.number)} key={`${pr.repository}-${pr.number}`}><span><b>#{pr.number} {pr.title}</b><small>{pr.author} · {pr.state === "merged" ? "マージ済み" : pr.state === "draft" ? "下書き" : "レビュー中"}</small></span>{imported(pr) && <em>取込済み</em>}</button>)}</div>{selected && <section className="changelog-preview"><div className="preview-title"><span>生成されるチェンジログ</span><b>{selected.title}</b></div><p>{selected.body}</p><dl><div><dt>リポジトリ / PR</dt><dd>{selected.repository} #{selected.number}</dd></div><div><dt>revision</dt><dd>{selected.revision}</dd></div><div><dt>差分</dt><dd>+{selected.additions} / −{selected.deletions} · {selected.changedFiles.length}ファイル</dd></div><div><dt>migration</dt><dd>{migrationDetected ? "検出あり · onlineとして登録" : "検出なし"}</dd></div><div><dt>停止・メンテナンス</dt><dd>{selected.labels.includes("blocking-migration") ? "要確認" : "不要"}</dd></div></dl><div className="detection-evidence"><b>検出根拠</b><span>{selected.labels.map((label) => <i key={label}>{label}</i>)}</span>{selected.changedFiles.map((file) => <code key={file}>{file}</code>)}</div><button className="primary import-submit" disabled={imported(selected)} onClick={add}>{imported(selected) ? "このPRは取込済み" : "リリース変更として追加"}</button></section>}</div></section></div>;
}

function ChangeDetail({ change, changes, release }: { change: ComponentChange; changes: ComponentChange[]; release: Release }) { const data = useData(); const c = component(data, change.componentId)!; const transition = versionTransition(change, c, release); const pr = change.pullRequests[0]; const deps = change.dependencyIds.map((dep) => changes.find((item) => item.id === dep)).filter(Boolean).map((item) => component(data, item!.componentId)?.name).join("、") || "なし"; return <aside className="change-detail"><span className="eyebrow">{c.name} · {team(data, change.ownerTeamId)?.name}</span><h2>{change.summary}</h2><div className="pr-link">{pr?.repository} #{pr?.number} · {pr?.revision}</div><section className="version-transition-summary"><span>バージョン遷移</span><b>{transition.currentVersion} → {transition.targetVersion}</b><small>{dateTimeText(transition.startsAt)}開始 · {dateTimeText(transition.expectedCompletionAt)}到達予定</small><em className={`coexistence ${transition.coexistence}`}>{coexistenceText(transition.coexistence)}</em></section>{pr?.description && <section className="recorded-changelog"><span>PRチェンジログ</span><p>{pr.description}</p><div><b>差分</b><em>+{pr.additions} / −{pr.deletions} · {pr.changedFiles?.length ?? 0}ファイル</em></div>{pr.labels && <div className="recorded-labels">{pr.labels.map((label) => <i key={label}>{label}</i>)}</div>}</section>}<dl className="change-facts"><Fact name="migration" value={change.migration.required ? `${change.migration.phase} · ${change.migration.execution}` : "なし"} /><Fact name="停止・メンテナンス" value={maintenanceText(change.maintenance)} /><Fact name="依存する変更" value={deps} /><Fact name="反映予定" value={change.deploymentWindow} /><Fact name="回復方法" value={change.recovery} wide /></dl></aside>; }
function Fact({ name, value, wide }: { name: string; value: string; wide?: boolean }) { return <div className={wide ? "wide" : ""}><dt>{name}</dt><dd>{value}</dd></div>; }

function DependencyMap({ release }: { release: Release }) {
  const data = useData(); const [zoom, setZoom] = useState(1); const [mode, setMode] = useState<"select" | "hand" | "connector">("select"); const [selected, setSelected] = useState<string | null>(null); const changes = getChanges(release); const groups = groupChanges(data, changes); const stages = buildComponentStages(groups); const positions = new Map<string, { x: number; y: number }>();
  stages.forEach((stage, column) => stage.forEach((group, row) => positions.set(group.component.id, { x: 44 + column * 330, y: 68 + row * 202 })));
  const width = Math.max(980, stages.length * 330 + 50); const height = Math.max(500, Math.max(...stages.map((stage) => stage.length), 1) * 202 + 80); const byChange = new Map(changes.map((change) => [change.id, change])); const edgeMap = new Map<string, { sourceId: string; targetId: string; label: string }>();
  groups.forEach((target) => target.changes.forEach((change) => change.dependencyIds.forEach((dependencyId) => { const sourceChange = byChange.get(dependencyId); if (!sourceChange || sourceChange.componentId === target.component.id) return; const sourceComponent = component(data, sourceChange.componentId)!; const key = `${sourceComponent.id}-${target.component.id}`; const label = ["ios", "android"].includes(target.component.kind) && sourceComponent.kind === "backend" ? "API互換性確認後" : sourceChange.migration.phase === "contract" ? "100%到達後" : "反映・検証後"; edgeMap.set(key, { sourceId: sourceComponent.id, targetId: target.component.id, label }); }))); const edges = [...edgeMap.values()].map((edge) => ({ ...edge, source: positions.get(edge.sourceId), target: positions.get(edge.targetId) })).filter((edge) => edge.source && edge.target);
  return <section className="dependency-view"><div className="view-head"><div><span className="eyebrow">{groups.length}コンポーネント · {changes.length}変更</span><h1>依存マップ</h1></div><div className="view-summary">コンポーネント間依存 {edges.length}件 · 新旧共存 {groups.filter((group) => versionTransition(group.changes[0], group.component, release).rollout !== "immediate").length}件</div></div><div className="dependency-board"><div className="board-legend"><span><i className="map-dot root" />先行条件なし</span><span><i className="map-dot dependent" />依存あり</span><span>ノード内: コンポーネント変更</span></div><div className="zoom-control"><button onClick={() => setZoom((value) => Math.max(.6, value - .1))}>−</button><span>{Math.round(zoom * 100)}%</span><button onClick={() => setZoom((value) => Math.min(1.5, value + .1))}>＋</button><button onClick={() => setZoom(1)}>全体</button></div><div className={`dependency-scroll mode-${mode}`}><div className="dependency-canvas" style={{ width, height, transform: `scale(${zoom})` }}><div className="map-stage-labels">{stages.map((_, index) => <span key={index} style={{ left: 44 + index * 330 }}>依存レベル {index + 1}</span>)}</div><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none">{edges.map((edge) => { const midX = (edge.source!.x + 252 + edge.target!.x) / 2; const midY = (edge.source!.y + edge.target!.y) / 2 + 76; return <g key={`${edge.sourceId}-${edge.targetId}`}><path d={`M ${edge.source!.x + 252} ${edge.source!.y + 76} C ${edge.source!.x + 292} ${edge.source!.y + 76}, ${edge.target!.x - 40} ${edge.target!.y + 76}, ${edge.target!.x} ${edge.target!.y + 76}`} /><polygon points={`${edge.target!.x - 8},${edge.target!.y + 71} ${edge.target!.x},${edge.target!.y + 76} ${edge.target!.x - 8},${edge.target!.y + 81}`} /><text x={midX} y={midY - 8}>{edge.label}</text></g>; })}</svg>{groups.map((group) => { const position = positions.get(group.component.id)!; const transition = versionTransition(group.changes[0], group.component, release); const dependent = group.changes.some((change) => change.dependencyIds.length); return <article onClick={() => mode === "select" && setSelected(group.component.id)} className={`map-node component-map-node kind-${group.component.kind} ${dependent ? "dependent" : "root"} ${selected === group.component.id ? "selected" : ""}`} style={{ left: position.x, top: position.y }} key={group.component.id}><header><b>{group.component.name}</b><span>{team(data, group.component.ownerTeamId)?.name}</span></header><div className="map-version"><b>{transition.currentVersion} → {transition.targetVersion}</b><span>{rolloutText(transition.rollout)} · {coexistenceText(transition.coexistence)}</span></div><div className="map-change-list">{group.changes.map((change) => <p key={change.id}><span>PR #{change.pullRequests[0]?.number}</span>{change.summary}</p>)}</div><footer><span>{dateTimeText(transition.startsAt)}開始</span><span>{dateTimeText(transition.expectedCompletionAt)}到達</span></footer>{transition.rollout !== "immediate" && <small>配信中は新旧バージョンが同時稼働</small>}</article>; })}</div></div><div className="board-tools" role="toolbar" aria-label="依存マップのツール"><button className={mode === "select" ? "active" : ""} onClick={() => setMode("select")} title="選択">↖</button><button className={mode === "hand" ? "active" : ""} onClick={() => setMode("hand")} title="移動">✋</button><span /><button className={mode === "connector" ? "active" : ""} onClick={() => setMode("connector")} title="依存関係">↗</button></div></div></section>;
}

function Plan({ release }: { release: Release }) {
  const data = useData(); const changes = getChanges(release); const groups = groupChanges(data, changes); const [planning, setPlanning] = useState<ComponentChangeGroup | null>(null); const transitions = groups.map((group) => ({ group, transition: versionTransition(group.changes[0], group.component, release) })); const risks = releasePlanRisks(data, release, groups); const range = timelineRange(transitions.map((item) => item.transition)); const ticks = Array.from({ length: 6 }, (_, index) => new Date(range.start + ((range.end - range.start) * index) / 5)); const mobileCompletion = Math.max(...transitions.filter((item) => ["ios", "android"].includes(item.group.component.kind)).map((item) => new Date(item.transition.expectedCompletionAt).getTime()), 0); const contractAfter = new Date(mobileCompletion + 24 * 60 * 60 * 1000);
  return <section className="plan-view"><div className="view-head"><div><span className="eyebrow">コンポーネント別バージョン遷移</span><h1>実行計画</h1></div><div className="view-summary">{groups.length}コンポーネント · 新旧共存 {transitions.filter((item) => item.transition.rollout !== "immediate").length}件 · リスク {risks.length}件</div></div><PlanDecisionPanel release={release} /><div className="plan-layout timeline-plan"><div className="version-timeline"><div className="timeline-axis"><span>コンポーネント</span><div>{ticks.map((tick) => <time key={tick.toISOString()}>{shortDateTime(tick)}</time>)}</div></div>{transitions.map(({ group, transition }) => <TimelineLane key={group.component.id} component={group.component} changes={group.changes} transition={transition} range={range} edit={() => setPlanning(group)} />)}{mobileCompletion > 0 && <section className="compatibility-gate"><b>互換性維持期間</b><span>バックエンドの旧APIとexpand schemaは、モバイルの100%到達予定である{dateTimeText(new Date(mobileCompletion).toISOString())}まで維持します。</span><em>contract migration: {dateText(contractAfter.toISOString().slice(0, 10))}以降</em></section>}</div><aside className="risk-panel"><span className="eyebrow">計画上のリスク</span><h2>{risks.length}件</h2>{risks.map((risk, index) => <div className={`risk-item ${risk.level}`} key={`${risk.title}-${index}`}><span>{risk.level === "high" ? "高" : risk.level === "medium" ? "中" : "低"}</span><div><small>{risk.scope}</small><b>{risk.title}</b><p>{risk.body}</p><em>{risk.control}</em></div></div>)}<div className="release-policy"><b>計画判定</b><span>{risks.some((risk) => risk.level === "high") ? "条件付き" : "実行可能"}</span></div></aside></div>{planning && <ComponentPlanForm release={release} group={planning} close={() => setPlanning(null)} />}</section>;
}

function PlanDecisionPanel({ release }: { release: Release }) { const data = useData(); const currentRevision = graphRevision(release); const decision = release.planDecision; const stale = Boolean(decision && decision.graphRevision !== currentRevision); const generate = () => { const candidates = derivePlanCandidates(data, release); updateRelease(data, release.id, (current) => ({ ...current, approvalStatus: ["approved", "conditionally-approved", "pending"].includes(current.approvalStatus ?? "") ? "invalidated" : current.approvalStatus, approvedPlanRevision: undefined, planDecision: { graphRevision: currentRevision, generatedAt: new Date().toISOString(), candidates, selectedPlanId: candidates[1]?.id ?? candidates[0]?.id }, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "plan", occurredAt: new Date().toISOString(), actor: "System", summary: "依存マップから実行計画候補を生成", detail: `${candidates.length}候補 · ${currentRevision}` }] })); }; const select = (candidateId: string) => updateRelease(data, release.id, (current) => { if (!current.planDecision || current.planDecision.selectedPlanId === candidateId) return current; return { ...current, approvalStatus: ["approved", "conditionally-approved", "pending"].includes(current.approvalStatus ?? "") ? "invalidated" : current.approvalStatus, approvedPlanRevision: undefined, planDecision: { ...current.planDecision, selectedPlanId: candidateId, evaluation: undefined }, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "plan", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "実行計画候補を変更", detail: current.planDecision.candidates.find((candidate) => candidate.id === candidateId)?.name }] }; }); const evaluate = () => updateRelease(data, release.id, (current) => { if (!current.planDecision || current.planDecision.graphRevision !== graphRevision(current)) return current; const evaluation = mockJevEvaluation(current.planDecision.candidates); return { ...current, planDecision: { ...current.planDecision, selectedPlanId: evaluation.selectedPlanId, evaluation }, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "jev", occurredAt: evaluation.evaluatedAt, actor: "Jev mock", summary: "実行計画を評価", detail: `${recommendationText(evaluation.recommendation)} · リスク ${evaluation.riskScore}/5 · confidence ${Math.round(evaluation.confidence * 100)}%` }] }; }); return <section className="plan-decision-panel"><header><div><span className="eyebrow">依存マップから導出</span><h2>計画候補とJev評価</h2></div><div className="plan-decision-actions"><code>{currentRevision}</code><button className="ghost" onClick={generate}>{decision ? "計画候補を再生成" : "計画候補を生成"}</button>{decision && !stale && <button className="primary" onClick={evaluate}>Jevモックで評価</button>}</div></header>{stale && <div className="stale-plan"><b>依存マップまたは予定が変更されています</b><span>以前の計画候補とJev評価は承認に利用できません。候補を再生成してください。</span></div>}{!decision && <p className="plan-empty">依存関係、migration、バージョン切替、検証条件から実行可能な候補を生成します。</p>}{decision && !stale && <div className="plan-candidates">{decision.candidates.map((candidate) => <button className={decision.selectedPlanId === candidate.id ? "selected" : ""} onClick={() => select(candidate.id)} key={candidate.id}><header><b>{candidate.name}</b><span>決定的リスク {candidate.deterministicRisk.toFixed(1)}</span></header><p>{candidate.summary}</p><small>{dateTimeText(candidate.estimatedCompletionAt)} 完了見込</small><em>{candidate.conditions.length}条件</em></button>)}</div>}{decision?.evaluation && !stale && <div className="jev-plan-result"><span className="demo-badge">Jevモック · API未接続</span><b>{recommendationText(decision.evaluation.recommendation)}</b><p>選択: {decision.candidates.find((candidate) => candidate.id === decision.evaluation?.selectedPlanId)?.name} · リスク {decision.evaluation.riskScore}/5 · confidence {Math.round(decision.evaluation.confidence * 100)}%</p><div>{Object.entries(decision.evaluation.categories).map(([key, value]) => <span key={key}>{riskCategoryText[key] ?? key} {value.toFixed(1)}</span>)}</div><ul>{decision.evaluation.conditions.map((condition) => <li key={condition}>{condition}</li>)}</ul></div>}</section>; }

const runbookPhaseText: Record<RunbookStep["phase"], string> = { precheck: "実行前確認", migration: "migration", deploy: "反映", verify: "検証", rollout: "段階配信", close: "完了判定" };

function Runbook({ release }: { release: Release }) {
  const data = useData(); const revision = graphRevision(release); const decision = release.planDecision; const evaluated = decision?.graphRevision === revision && decision.evaluation?.selectedPlanId === decision.selectedPlanId; const selectedPlan = decision?.candidates.find((candidate) => candidate.id === decision.selectedPlanId); const runbook = release.runbook; const current = Boolean(runbook && runbook.graphRevision === revision && runbook.planId === decision?.selectedPlanId); const componentIds = new Set(getChanges(release).map((change) => change.componentId)); const readmes = repositoryReadmes.filter((readme) => componentIds.has(readme.componentId));
  const generate = () => { if (!decision || !evaluated) return; const steps = generateRunbookSteps(data, release, readmes); updateRelease(data, release.id, (target) => ({ ...target, runbook: { graphRevision: revision, planId: decision.selectedPlanId, generatedAt: new Date().toISOString(), mock: true, sourceDocuments: readmes.map(({ repository, path, revision: sourceRevision }) => ({ repository, path, revision: sourceRevision })), steps }, history: [...releaseHistory(target), { id: id(crypto.randomUUID()), type: "runbook", occurredAt: new Date().toISOString(), actor: "Jev mock", summary: "リリース手順書を生成", detail: `${selectedPlan?.name} · ${readmes.length} README · ${steps.length}手順` }] })); };
  return <section className="runbook-view"><div className="view-head"><div><span className="eyebrow">{revision}{selectedPlan ? ` · ${selectedPlan.name}` : ""}</span><h1>リリース手順書</h1></div><div className="view-actions"><span className="demo-badge">Jevモック · API未接続</span><button className="primary" disabled={!evaluated} onClick={generate}>{runbook ? "手順書を再生成" : "Jevモックで手順書を生成"}</button></div></div>{!evaluated && <section className="runbook-gate"><div><b>現在の実行計画に対するJev評価が必要です</b><span>依存マップから計画候補を生成し、Jevモックで評価すると手順書を生成できます。</span></div><Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画へ</Link></section>}{runbook && !current && <section className="stale-plan runbook-stale"><b>この手順書は現在の計画と一致しません</b><span>依存マップ、予定、または選択した計画が変更されています。実行には使用せず、Jev評価後に再生成してください。</span></section>}{runbook && current && <div className="runbook-layout"><div className="runbook-steps"><header><div><span className="eyebrow">生成日時</span><b>{dateTimeText(runbook.generatedAt)}</b></div><span>{runbook.steps.length}手順</span></header>{runbook.steps.map((step) => { const target = step.componentId ? component(data, step.componentId) : undefined; const owner = target ? team(data, target.ownerTeamId) : undefined; return <article className="runbook-step" key={step.id}><div className="runbook-order">{String(step.order).padStart(2, "0")}</div><div><header><span>{runbookPhaseText[step.phase]}</span>{target && <em>{target.name} · {owner?.name}</em>}</header><h2>{step.title}</h2><p>{step.instruction}</p>{step.command && <div className="runbook-command"><span>README記載コマンド</span><code>{step.command}</code></div>}<dl><div><dt>期待結果</dt><dd>{step.expectedResult}</dd></div>{step.stopCondition && <div><dt>中止条件</dt><dd>{step.stopCondition}</dd></div>}{step.recovery && <div><dt>復旧方法</dt><dd>{step.recovery}</dd></div>}</dl><footer>{step.sourceRefs.map((source) => <span key={source}>{source}</span>)}</footer></div></article>; })}</div><aside className="runbook-sources"><span className="eyebrow">参照したREADMEモック</span><h2>{runbook.sourceDocuments.length}リポジトリ</h2><p>実際のGitHub APIには未接続です。以下の固定スナップショットを参照しています。</p>{readmes.map((readme) => <details open key={readme.repository}><summary><b>{readme.repository}</b><span>{readme.path} · {readme.revision}</span></summary><p>{readme.summary}</p><ul>{readme.cautions.map((caution) => <li key={caution}>{caution}</li>)}</ul></details>)}</aside></div>}{!runbook && evaluated && <section className="runbook-empty"><b>手順書はまだ生成されていません</b><span>{readmes.length}件のREADMEモック、コンポーネント変更、検証項目、選択した実行計画を入力として生成します。</span></section>}</section>;
}
function TimelineLane({ component: target, changes, transition, range, edit }: { component: Component; changes: ComponentChange[]; transition: VersionTransition; range: { start: number; end: number }; edit?: () => void }) { const start = percentAt(transition.startsAt, range); const end = percentAt(transition.expectedCompletionAt, range); return <article className={`timeline-lane kind-${target.kind}`}><header><b>{target.name}</b><span>{transition.currentVersion} → {transition.targetVersion}</span><small>{versionSourceText(transition.versionSource)} · {changes.map((change) => `#${change.pullRequests[0]?.number}`).join(" · ")}</small>{edit && <button onClick={edit}>バージョン計画を編集</button>}</header><div className="lane-track"><div className="old-version" style={{ width: `${start}%` }}><span>{transition.currentVersion}</span></div><div className={`rollout-window ${transition.rollout}`} style={{ left: `${start}%`, width: `${Math.max(end - start, transition.rollout === "immediate" ? .3 : 1.5)}%` }}><b>{rolloutText(transition.rollout)}</b><small>{coexistenceText(transition.coexistence)}</small></div><div className="target-version" style={{ left: `${end}%` }}><span>{transition.targetVersion}</span></div>{transition.adoptionMilestones.filter((milestone) => milestone.percentage < 100).map((milestone) => <i className="milestone" style={{ left: `${percentAt(milestone.at, range)}%` }} key={`${milestone.at}-${milestone.percentage}`}><span>{milestone.percentage}%</span></i>)}</div><footer><span>{dateTimeText(transition.startsAt)} 切替開始</span><span>{dateTimeText(transition.expectedCompletionAt)} 100%到達予定</span></footer></article>; }

function Verifications({ release }: { release: Release }) { const data = useData(); return <section className="work-view"><CollectionHeader count={release.verifications.length} title="検証" /><div className="verification-table"><div className="verification-head"><span>対象</span><span>検証内容</span><span>実施条件</span><span>担当</span><span>状態</span></div>{release.verifications.map((item) => { const change = getChanges(release).find((candidate) => candidate.id === item.componentChangeId); return <div className="verification-row" key={item.id}><span>{change && component(data, change.componentId)?.name}</span><span>{item.name}</span><span>{item.condition}</span><span>{team(data, item.ownerTeamId)?.name}</span><span>{({ pending: "未実施", running: "進行中", passed: "成功", failed: "失敗" })[item.status]}</span></div>; })}</div></section>; }

function ApprovalSchedule({ release }: { release: Release }) { const data = useData(); const scheduledAt = release.scheduledAt ?? `${release.scheduledFor}T10:00`; const approval = release.approvalStatus ?? "not-requested"; const revision = graphRevision(release); const evaluation = release.planDecision?.graphRevision === revision ? release.planDecision.evaluation : undefined; const selectedPlan = release.planDecision?.candidates.find((candidate) => candidate.id === release.planDecision?.selectedPlanId); const requestApproval = () => { if (!evaluation) return; updateRelease(data, release.id, (current) => ({ ...current, approvalStatus: "pending", approvedPlanRevision: revision, history: [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "approval", occurredAt: new Date().toISOString(), actor: "Taross K.", summary: "実行計画の承認を申請", detail: `${selectedPlan?.name} · ${revision}` }] })); };
  const saveSchedule = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const nextAt = str(f, "scheduledAt"); const actor = str(f, "actor"); const record = f.get("recordHistory") === "on"; updateRelease(data, release.id, (current) => { const updated: Release = { ...current, scheduledAt: nextAt, scheduledFor: nextAt.slice(0, 10), considerations: str(f, "considerations"), notes: str(f, "notes"), history: record ? [...releaseHistory(current), { id: id<"ReleaseHistoryEntry">(crypto.randomUUID()), type: "schedule", occurredAt: new Date().toISOString(), actor, summary: `リリース予定を${dateTimeText(nextAt)}へ変更`, detail: `${dateTimeText(current.scheduledAt ?? `${current.scheduledFor}T10:00`)}から変更` }] : current.history }; return nextAt === (current.scheduledAt ?? `${current.scheduledFor}T10:00`) ? updated : invalidatePlan(updated, "リリース予定日時が変更されました"); }); };
  const saveApproval = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const nextStatus = str(f, "approvalStatus") as ApprovalStatus; if (["approved", "conditionally-approved"].includes(nextStatus) && !evaluation) return alert("現在の依存マップに対するJev評価が必要です。"); const actor = str(f, "actor"); const note = str(f, "approvalNote"); const record = f.get("recordHistory") === "on"; updateRelease(data, release.id, (current) => ({ ...current, approvalStatus: nextStatus, approvedBy: actor, approvedPlanRevision: evaluation ? revision : current.approvedPlanRevision, history: record ? [...releaseHistory(current), { id: id(crypto.randomUUID()), type: "approval", occurredAt: new Date().toISOString(), actor, summary: `承認状態を「${approvalText[nextStatus]}」へ変更`, detail: `${note}${evaluation ? ` · ${revision}` : ""}` }] : current.history })); };
  return <section className="approval-view"><div className="view-head"><div><span className="eyebrow">予定変更と承認履歴</span><h1>承認・予定</h1></div><div className="approval-current"><span className={`approval-state ${approval}`}>{approvalText[approval]}</span><b>{dateTimeText(scheduledAt)}</b></div></div><section className={`approval-gate ${evaluation ? "ready" : "blocked"}`}><div><span className="eyebrow">実行計画の評価</span><h2>{evaluation ? recommendationText(evaluation.recommendation) : "Jev評価が必要です"}</h2><p>{evaluation ? `${selectedPlan?.name} · リスク ${evaluation.riskScore}/5 · confidence ${Math.round(evaluation.confidence * 100)}%` : "現在の依存マップから計画候補を生成し、Jevモック評価を実行してください。"}</p></div>{evaluation ? <><ul>{evaluation.conditions.map((condition) => <li key={condition}>{condition}</li>)}</ul><button className="primary" onClick={requestApproval} disabled={approval === "pending"}>{approval === "pending" ? "承認申請済み" : "この計画で承認申請"}</button></> : <Link className="ghost header-link" to={`/releases/${release.id}/plan`}>実行計画へ</Link>}</section><div className="approval-layout"><div className="approval-forms"><form className="release-control-form" onSubmit={saveSchedule}><header><div><span>リリース予定</span><h2>{dateTimeText(scheduledAt)}</h2></div><small>実行計画の基準時刻</small></header><label>予定日時<input name="scheduledAt" type="datetime-local" defaultValue={scheduledAt} required /></label><label>考慮事項<textarea name="considerations" defaultValue={release.considerations ?? "モバイル審査通過後に段階配信を開始。旧APIは100%到達まで維持。"} /></label><label>備考<textarea name="notes" defaultValue={release.notes ?? ""} placeholder="日程調整の背景や関係者への連絡事項" /></label><Input label="変更者" name="actor" value="Taross K." /><label className="history-option"><input name="recordHistory" type="checkbox" defaultChecked /><span><b>変更履歴に残す</b><small>入力訂正など、監査対象にしない変更では外せます。</small></span></label><button className="primary" type="submit">予定を保存</button></form><form className="release-control-form" onSubmit={saveApproval}><header><div><span>承認状態</span><h2>{approvalText[approval]}</h2></div><small>{release.approvedBy ? `最終更新: ${release.approvedBy}` : "承認者未登録"}</small></header><Choice label="変更後の承認状態" name="approvalStatus" value={approval} options={[["pending", "承認待ち"], ["approved", "承認済み"], ["conditionally-approved", "条件付き承認"], ["rejected", "差し戻し"], ["not-requested", "未申請"]]} /><Input label="承認・変更者" name="actor" value={release.approvedBy ?? "田中 健"} /><label>判断理由・差し戻し内容<textarea name="approvalNote" placeholder="承認条件または差し戻し理由" /></label><label className="history-option"><input name="recordHistory" type="checkbox" defaultChecked /><span><b>変更履歴に残す</b><small>単なる操作ミスの訂正では外せます。</small></span></label><button className="primary" type="submit">承認状態を保存</button></form></div><aside className="release-history"><span className="eyebrow">変更履歴</span><h2>{releaseHistory(release).length}件</h2>{[...releaseHistory(release)].reverse().map((entry) => <article key={entry.id}><i className={`history-type ${entry.type}`} /><div><header><b>{entry.summary}</b><time>{dateTimeText(entry.occurredAt)}</time></header><span>{entry.actor}</span>{entry.detail && <p>{entry.detail}</p>}</div></article>)}</aside></div></section>; }

function TeamList() { const data = useData(); const [editing, setEditing] = useState<Team | "new" | null>(null); const remove = (target: Team) => { if (data.components.some((item) => item.ownerTeamId === target.id) || data.releases.some((item) => item.ownerTeamId === target.id)) return alert("使用中のチームは削除できません。"); if (confirm(`${target.name}を削除しますか？`)) data.setTeams((items) => items.filter((item) => item.id !== target.id)); }; return <section className="collection-view"><CollectionHeader count={data.teams.length} title="チーム" action="チームを登録" onAction={() => setEditing("new")} /><div className="settings-table"><div className="settings-head team-columns with-actions"><span>チーム名</span><span>責任者</span><span>メンバー</span><span>担当コンポーネント</span><span /></div>{data.teams.map((item) => <div className="settings-row team-columns with-actions" key={item.id}><b>{item.name}</b><span>{item.lead}</span><span>{item.memberCount}名</span><span>{data.components.filter((c) => c.ownerTeamId === item.id).map((c) => c.name).join("、") || "未設定"}</span><Actions edit={() => setEditing(item)} remove={() => remove(item)} /></div>)}</div>{editing && <TeamForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>; }
function TeamForm({ target, close }: { target?: Team; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const next: Team = { id: target?.id ?? id(crypto.randomUUID()), name: str(f, "name"), lead: str(f, "lead"), memberCount: Number(f.get("members")) }; data.setTeams((items) => target ? items.map((item) => item.id === target.id ? next : item) : [...items, next]); close(); }; return <Dialog title={target ? "チームを編集" : "チームを登録"} close={close}><form onSubmit={save}><Input label="チーム名" name="name" value={target?.name} /><Input label="責任者" name="lead" value={target?.lead} /><Input label="メンバー数" name="members" type="number" value={String(target?.memberCount ?? 0)} /><Save /></form></Dialog>; }

function ComponentList() { const data = useData(); const [editing, setEditing] = useState<Component | "new" | null>(null); const remove = (target: Component) => { if (data.releases.some((release) => getChanges(release).some((change) => change.componentId === target.id))) return alert("リリースで使用中のコンポーネントは削除できません。"); if (confirm(`${target.name}を削除しますか？`)) data.setComponents((items) => items.filter((item) => item.id !== target.id)); }; return <section className="collection-view"><CollectionHeader count={data.components.length} title="コンポーネント" action="コンポーネントを登録" onAction={() => setEditing("new")} /><div className="settings-table"><div className="settings-head component-columns with-actions"><span>名称</span><span>種別</span><span>担当チーム</span><span>GitHubリポジトリ</span><span>反映方法</span><span /></div>{data.components.map((item) => <div className="settings-row component-columns with-actions" key={item.id}><b>{item.name}</b><span>{kindText(item.kind)}</span><span>{team(data, item.ownerTeamId)?.name}</span><span className="repository-cell"><a href={item.repositoryUrl ?? `https://github.com/${item.repository}`} target="_blank" rel="noreferrer">{item.repository}</a><small>モック接続 · {item.defaultBranch ?? "main"}</small></span><span>{item.deliveryMethod}</span><Actions edit={() => setEditing(item)} remove={() => remove(item)} /></div>)}</div>{editing && <ComponentForm target={editing === "new" ? undefined : editing} close={() => setEditing(null)} />}</section>; }
function ComponentForm({ target, close }: { target?: Component; close: () => void }) { const data = useData(); const save = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); const repository = str(f, "repository"); const next: Component = { id: target?.id ?? id(crypto.randomUUID()), name: str(f, "name"), kind: str(f, "kind") as ComponentKind, ownerTeamId: id(str(f, "team")), repository, repositoryUrl: str(f, "repositoryUrl") || `https://github.com/${repository}`, defaultBranch: str(f, "defaultBranch"), githubConnection: "mock", deliveryMethod: str(f, "delivery") }; data.setComponents((items) => target ? items.map((item) => item.id === target.id ? next : item) : [...items, next]); close(); }; return <Dialog title={target ? "コンポーネントを編集" : "コンポーネントを登録"} close={close}><form onSubmit={save}><Input label="名称" name="name" value={target?.name} /><Choice label="種別" name="kind" value={target?.kind} options={[["ios", "iOSアプリ"], ["android", "Androidアプリ"], ["backend", "バックエンド"], ["admin", "Webアプリ"]]} /><Choice label="担当チーム" name="team" value={target?.ownerTeamId} options={data.teams.map((item) => [item.id, item.name])} /><Input label="GitHubリポジトリ（owner/name）" name="repository" value={target?.repository} /><Input label="GitHub URL" name="repositoryUrl" type="url" value={target?.repositoryUrl ?? (target?.repository ? `https://github.com/${target.repository}` : "")} /><Input label="デフォルトブランチ" name="defaultBranch" value={target?.defaultBranch ?? "main"} /><Input label="反映方法" name="delivery" value={target?.deliveryMethod} /><div className="connection-note"><b>接続方式</b><span>GitHubモック。実API接続時はGitHub AppのInstallation IDを保存します。</span></div><Save /></form></Dialog>; }

function JevRiskDemo({ release, close }: { release: Release; close: () => void }) {
  const data = useData(); const [state, setState] = useState<"idle" | "running" | "done">("idle"); const changes = getChanges(release);
  const migrations = changes.filter((item) => item.migration.required); const blocking = migrations.filter((item) => item.migration.execution === "blocking"); const unknown = changes.filter((item) => item.maintenance === "undetermined"); const missingRecovery = changes.filter((item) => !item.recovery.trim()); const mobile = changes.filter((item) => ["ios", "android"].includes(component(data, item.componentId)?.kind ?? ""));
  const hardIssues = unknown.length + missingRecovery.length + (hasCycle(changes) ? 1 : 0); const riskScore = Math.min(5, 1.4 + migrations.length * .55 + blocking.length * 1.2 + mobile.length * .25 + hardIssues * 1.3); const stagedProbability = hardIssues ? .38 : .86; const proceedProbability = hardIssues ? .31 : .88;
  const run = () => { setState("running"); window.setTimeout(() => setState("done"), 650); };
  return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal jev-demo"><button className="panel-close" onClick={close}>×</button><div className="jev-heading"><span className="demo-badge">モック判定 · API未接続</span><h2>Jevリスク判定</h2><p>実際のJev出力を模した型付き判定です。値はデモ用で、リリース判断には使用しません。</p></div><div className="jev-flow">
    <section><span className="step-number">01</span><div><h3>入力状態</h3><dl className="jev-input"><div><dt>コンポーネント変更</dt><dd>{changes.length}件</dd></div><div><dt>依存関係</dt><dd>{changes.reduce((sum, item) => sum + item.dependencyIds.length, 0)}件</dd></div><div><dt>migration</dt><dd>{migrations.length}件</dd></div><div><dt>blocking migration</dt><dd>{blocking.length}件</dd></div><div><dt>モバイル配布</dt><dd>{mobile.length}件</dd></div><div><dt>停止要否未判定</dt><dd>{unknown.length}件</dd></div></dl></div></section>
    <section><span className="step-number">02</span><div><h3>Jevへの型付き質問</h3><div className="typed-question"><b>choice</b><span>推奨する公開方式</span><code>段階公開 / メンテナンスモード / サービス停止</code></div><div className="typed-question"><b>score</b><span>リリースリスク</span><code>1（低）〜 5（高）</code></div><div className="typed-question"><b>yes / no</b><span>現在の計画で進行可能か</span><code>確率とconfidence</code></div></div></section>
    {state === "idle" && <button className="primary jev-run" onClick={run}>モック判定を実行</button>}{state === "running" && <div className="jev-running"><i />型付き判定を実行中</div>}{state === "done" && <><section><span className="step-number">03</span><div><h3>Jev出力（モック）</h3><DecisionBar label="段階公開" value={stagedProbability} selected /><DecisionBar label="メンテナンスモード" value={hardIssues ? .44 : .1} /><DecisionBar label="サービス停止" value={hardIssues ? .18 : .04} /><div className="score-output"><span>リスクスコア</span><b>{riskScore.toFixed(1)} / 5</b></div><div className="score-output"><span>進行可能</span><b>{Math.round(proceedProbability * 100)}%</b></div></div></section><section><span className="step-number">04</span><div><h3>ルールエンジンによる再検証</h3><div className={`rule-result ${hardIssues ? "failed" : "passed"}`}><b>{hardIssues ? "計画を確定できません" : "必須制約を満たしています"}</b><span>{hardIssues ? `未解決項目 ${hardIssues}件。Jevの推奨よりルール違反を優先します。` : "循環依存、停止要否未判定、回復方法の欠落はありません。"}</span></div></div></section><section><span className="step-number">05</span><div><h3>アプリケーションの判断</h3><div className="final-decision"><span>{hardIssues ? "保留" : "推奨"}</span><b>{hardIssues ? "未解決項目を修正後に再判定" : "停止なしで段階公開"}</b><p>{hardIssues ? "型付き判定だけでGo/No-Goを決めません。" : "バックエンドを先行し、検証後にモバイルを段階公開します。"}</p></div></div></section></>}
  </div><footer className="jev-footnote">Early Access取得後は、同じ入力・質問スキーマをサーバー側アダプターからJevへ送信します。</footer></section></div>;
}

function DecisionBar({ label, value, selected }: { label: string; value: number; selected?: boolean }) { return <div className={`decision-bar ${selected ? "selected" : ""}`}><span>{label}</span><i><em style={{ width: `${value * 100}%` }} /></i><b>{Math.round(value * 100)}%</b></div>; }

function CollectionHeader({ count, title, action, onAction }: { count: number; title: string; action?: string; onAction?: () => void }) { return <div className="view-head"><div><span className="eyebrow">全 {count}件</span><h1>{title}</h1></div>{action && <button className="primary" onClick={onAction}>＋ {action}</button>}</div>; }
function Actions({ edit, remove }: { edit: () => void; remove: () => void }) { return <span className="row-actions"><button onClick={(event) => { event.preventDefault(); event.stopPropagation(); edit(); }}>編集</button><button className="danger" onClick={(event) => { event.preventDefault(); event.stopPropagation(); remove(); }}>削除</button></span>; }
function Dialog({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className="modal-root"><button className="backdrop" aria-label="閉じる" onClick={close} /><section className="modal form-modal"><button className="panel-close" onClick={close}>×</button><h2>{title}</h2>{children}</section></div>; }
function Input({ label, name, value, type = "text" }: { label: string; name: string; value?: string; type?: string }) { return <label>{label}<input name={name} type={type} defaultValue={value} required /></label>; }
function Choice({ label, name, value, options }: { label: string; name: string; value?: string; options: [string, string][] }) { return <label>{label}<select name={name} defaultValue={value}>{options.map(([key, text]) => <option value={key} key={key}>{text}</option>)}</select></label>; }
function Save() { return <button className="primary form-submit" type="submit">保存</button>; }
function Empty({ text }: { text: string }) { return <div className="empty-state"><p>{text}</p></div>; }
function NotFound() { return <div className="empty-state"><p>対象が見つかりません</p><Link className="primary" to="/releases">リリース一覧へ</Link></div>; }

const str = (form: FormData, key: string) => String(form.get(key) ?? "");
const getChanges = (release: Release) => release.featureChanges.flatMap((feature) => feature.componentChanges);
const team = (data: Store, teamId: Team["id"]) => data.teams.find((item) => item.id === teamId);
const component = (data: Store, componentId: Component["id"]) => data.components.find((item) => item.id === componentId);
const updateRelease = (data: Store, releaseId: Release["id"], update: (release: Release) => Release) => data.setReleases((items) => items.map((item) => item.id === releaseId ? update(item) : item));
const dateText = (date: string) => new Intl.DateTimeFormat("ja-JP", { year: "numeric", month: "long", day: "numeric" }).format(new Date(`${date}T00:00:00`));
const maintenanceText = (value: ComponentChange["maintenance"]) => ({ none: "不要", "maintenance-mode": "メンテナンスモード", "service-stop": "サービス停止", undetermined: "未判定" })[value];
const kindText = (value: ComponentKind) => ({ ios: "iOSアプリ", android: "Androidアプリ", backend: "バックエンド", admin: "Webアプリ" })[value];
const approvalText: Record<ApprovalStatus, string> = { "not-requested": "未申請", pending: "承認待ち", approved: "承認済み", "conditionally-approved": "条件付き承認", rejected: "差し戻し", invalidated: "承認失効" };
const recommendationText = (value: "accept" | "accept-with-conditions" | "revise" | "reject") => ({ accept: "承認申請可能", "accept-with-conditions": "条件付きで承認申請可能", revise: "計画修正を推奨", reject: "計画を棄却" })[value];
const riskCategoryText: Record<string, string> = { compatibility: "互換性", rollout: "配信", recovery: "回復", verification: "検証", schedule: "日程" };
const versionSourceText = (value: VersionTransition["versionSource"]) => ({ manual: "手入力", github: "GitHub Actions artifact", deployment: "デプロイ環境（モック）", "app-store": "App Store Connect（モック）", "google-play": "Google Play Console（モック）" })[value ?? "manual"];
function releaseHistory(release: Release) { if (release.history) return release.history; const created = new Date(`${release.scheduledFor}T10:00:00`); created.setDate(created.getDate() - 14); return [{ id: id<"ReleaseHistoryEntry">(`created-${release.id}`), type: "note" as const, occurredAt: created.toISOString(), actor: "Taross K.", summary: "リリースを作成", detail: `${release.code} ${release.name}` }]; }
type ComponentChangeGroup = { component: Component; changes: ComponentChange[]; dependencyComponentIds: Component["id"][] };
function groupChanges(data: Store, changes: ComponentChange[]): ComponentChangeGroup[] { return data.components.map((target) => { const grouped = changes.filter((change) => change.componentId === target.id); const dependencies = grouped.flatMap((change) => change.dependencyIds).map((dependencyId) => changes.find((change) => change.id === dependencyId)?.componentId).filter((componentId): componentId is Component["id"] => Boolean(componentId) && componentId !== target.id); return { component: target, changes: grouped, dependencyComponentIds: [...new Set(dependencies)] }; }).filter((group) => group.changes.length); }
function generateRunbookSteps(data: Store, release: Release, readmes: RepositoryReadme[]): RunbookStep[] {
  const groups = buildComponentStages(groupChanges(data, getChanges(release))).flat(); const selected = release.planDecision?.candidates.find((candidate) => candidate.id === release.planDecision?.selectedPlanId); const steps: RunbookStep[] = []; const add = (step: Omit<RunbookStep, "id" | "order">) => steps.push({ ...step, id: `runbook-${steps.length + 1}`, order: steps.length + 1 });
  add({ phase: "precheck", title: "対象revisionと実行条件を照合", instruction: `選択した「${selected?.name ?? "実行計画"}」の条件、対象PR、各コンポーネントの変更後バージョンを照合する。`, expectedResult: "全PRのrevision、担当チーム、反映予定が手順書と一致している", stopCondition: "未mergeのPR、未判定の停止要否、未登録の復旧方法がある", sourceRefs: ["実行計画", ...readmes.map((readme) => `${readme.repository}/${readme.path}`)] });
  groups.forEach((group) => {
    const readme = readmes.find((item) => item.componentId === group.component.id); const transition = versionTransition(group.changes[0], group.component, release); const revision = group.changes.flatMap((change) => change.pullRequests)[0]?.revision ?? "<revision>"; const source = readme ? `${readme.repository}/${readme.path}@${readme.revision}` : "コンポーネント変更"; const migration = group.changes.find((change) => change.migration.required); const recovery = group.changes.map((change) => change.recovery).filter(Boolean).join("／");
    if (migration) add({ phase: "migration", componentId: group.component.id, title: `${migration.migration.phase} migrationを実行`, instruction: `${maintenanceText(migration.maintenance)}の条件で${migration.migration.execution === "blocking" ? "排他実行" : "online実行"}する。`, command: readme?.commands.find((item) => item.purpose.includes("migration"))?.command, expectedResult: `migrationが完了し、${migration.migration.backwardCompatible ? "変更前バージョンからも利用できる" : "後方互換なしとして停止条件が適用される"}`, stopCondition: "migrationエラー、ロック待ち、主要APIのエラー率上昇", recovery, sourceRefs: [source, `PR #${migration.pullRequests[0]?.number ?? "—"}`] });
    const deployCommand = readme?.commands.find((item) => !item.purpose.includes("migration"))?.command.replace("<revision>", revision);
    add({ phase: "deploy", componentId: group.component.id, title: `${transition.targetVersion}を反映`, instruction: `${dateTimeText(transition.startsAt)}に${group.changes.map((change) => change.summary).join("、")}を反映する。`, command: deployCommand, expectedResult: `${transition.currentVersion}から${transition.targetVersion}への切替が開始される`, stopCondition: "build失敗、artifact revision不一致、依存コンポーネントの検証未完了", recovery, sourceRefs: [source, ...group.changes.flatMap((change) => change.pullRequests.map((pr) => `${pr.repository}#${pr.number}@${pr.revision}`))] });
    release.verifications.filter((verification) => group.changes.some((change) => change.id === verification.componentChangeId)).forEach((verification) => add({ phase: "verify", componentId: group.component.id, title: verification.name, instruction: `${verification.condition}に${team(data, verification.ownerTeamId)?.name ?? "担当チーム"}が実行する。`, expectedResult: "検証結果を合格として記録できる", stopCondition: "期待結果との差異、または回帰項目の失敗", recovery, sourceRefs: ["検証項目", source] }));
    if (transition.rollout !== "immediate") add({ phase: "rollout", componentId: group.component.id, title: `${transition.targetVersion}の段階配信を監視`, instruction: transition.adoptionMilestones.map((milestone) => `${milestone.percentage}%: ${dateTimeText(milestone.at)}`).join("／"), expectedResult: `${dateTimeText(transition.expectedCompletionAt)}までに100%へ到達する`, stopCondition: "バージョン別エラー率が2%を超える、または本人確認完了率が基準値を下回る", recovery, sourceRefs: [source, "バージョン計画"] });
  });
  add({ phase: "close", title: "配信完了と互換性維持条件を確認", instruction: "モバイルの到達率、バージョン別メトリクス、残存する旧APIとschemaを確認し、リリース結果を記録する。", expectedResult: "全検証が合格し、100%到達または承認済みの継続監視へ移行している", stopCondition: "旧クライアントが残る間はcontract migrationを実行しない", sourceRefs: ["実行計画", "Jev評価条件"] });
  return steps;
}
function graphRevision(release: Release) { const source = JSON.stringify({ scheduledAt: release.scheduledAt ?? release.scheduledFor, changes: getChanges(release).map((change) => ({ id: change.id, componentId: change.componentId, dependencyIds: change.dependencyIds, migration: change.migration, maintenance: change.maintenance, recovery: change.recovery, prs: change.pullRequests.map((pr) => [pr.repository, pr.number, pr.revision]) })), componentPlans: release.componentPlans ?? [] }); let hash = 5381; for (let index = 0; index < source.length; index += 1) hash = ((hash << 5) + hash) ^ source.charCodeAt(index); return `graph-${(hash >>> 0).toString(16).padStart(8, "0")}`; }
function derivePlanCandidates(data: Store, release: Release): PlanCandidate[] { const groups = groupChanges(data, getChanges(release)); const stages = buildComponentStages(groups); const completion = Math.max(...groups.map((group) => new Date(versionTransition(group.changes[0], group.component, release).expectedCompletionAt).getTime()), new Date(release.scheduledAt ?? `${release.scheduledFor}T10:00`).getTime()); const stageText = stages.map((stage, index) => `${index + 1}. ${stage.map((group) => group.component.name).join("・")}`); const after = (hours: number) => new Date(completion + hours * 3600000).toISOString(); return [{ id: "plan-fastest", name: "依存順・最短", strategy: "fastest", summary: "依存条件を満たした工程から並列実行し、最短で配信を開始する。", estimatedCompletionAt: after(0), deterministicRisk: 3.8, steps: stageText, conditions: ["バックエンド検証後にモバイル配信を開始", "エラー率2%超過で配信停止"] }, { id: "plan-compatible", name: "互換性優先", strategy: "compatibility-first", summary: "バックエンドの互換性検証とFeature Flag確認後にモバイルを段階配信する。", estimatedCompletionAt: after(24), deterministicRisk: 2.4, steps: ["1. backend migration・API反映", "2. API契約テスト・旧版クライアント確認", "3. 管理画面反映", "4. iOS・Android段階配信", "5. 100%到達後にcontract migrationを許可"], conditions: ["旧APIをモバイル100%到達まで維持", "Feature Flagの停止操作を事前確認", "バージョン別メトリクスを監視"] }, { id: "plan-split", name: "分割リリース", strategy: "split", summary: "バックエンドと管理画面を先行し、モバイル配信を別の承認単位として開始する。", estimatedCompletionAt: after(72), deterministicRisk: 1.9, steps: ["1. backend・管理画面を反映", "2. 本番検証を24時間継続", "3. モバイル配信を再承認", "4. iOS・Android段階配信"], conditions: ["モバイル開始前に再承認", "先行反映機能をFeature Flagで無効化可能"] }]; }
function mockJevEvaluation(candidates: PlanCandidate[]) { const selected = candidates.find((candidate) => candidate.strategy === "compatibility-first") ?? candidates[0]; return { recommendation: "accept-with-conditions" as const, selectedPlanId: selected.id, riskScore: 2.6, confidence: .86, categories: { compatibility: 2.1, rollout: 3.2, recovery: 2.8, verification: 2.0, schedule: 2.9 }, conditions: ["旧APIをモバイル100%到達まで維持", "配信率25%でエラー率と本人確認完了率を再評価", "Feature Flagによる停止操作を承認前に検証"], evaluatedAt: new Date().toISOString(), mock: true }; }
function invalidatePlan(release: Release, reason: string): Release { if (!release.planDecision) return release; const invalidatesApproval = ["pending", "approved", "conditionally-approved"].includes(release.approvalStatus ?? ""); return { ...release, planDecision: undefined, approvalStatus: invalidatesApproval ? "invalidated" : release.approvalStatus, history: [...releaseHistory(release), { id: id(crypto.randomUUID()), type: "plan", occurredAt: new Date().toISOString(), actor: "System", summary: invalidatesApproval ? "計画変更により承認を失効" : "計画評価を無効化", detail: reason }] }; }
function buildComponentStages(groups: ComponentChangeGroup[]) { const remaining = new Set(groups.map((group) => group.component.id)); const done = new Set<string>(); const stages: ComponentChangeGroup[][] = []; while (remaining.size) { const stage = groups.filter((group) => remaining.has(group.component.id) && group.dependencyComponentIds.every((dependency) => done.has(dependency) || !remaining.has(dependency))); if (!stage.length) { stages.push(groups.filter((group) => remaining.has(group.component.id))); break; } stages.push(stage); stage.forEach((group) => { remaining.delete(group.component.id); done.add(group.component.id); }); } return stages; }
function hasCycle(changes: ComponentChange[]) { const ids = new Set(changes.map((item) => item.id)); const visiting = new Set<string>(); const visited = new Set<string>(); const visit = (changeId: string): boolean => { if (visiting.has(changeId)) return true; if (visited.has(changeId)) return false; visiting.add(changeId); const change = changes.find((item) => item.id === changeId); if (change?.dependencyIds.filter((dependency) => ids.has(dependency)).some(visit)) return true; visiting.delete(changeId); visited.add(changeId); return false; }; return changes.some((item) => visit(item.id)); }
const rolloutText = (value: VersionTransition["rollout"]) => ({ immediate: "即時切替", phased: "段階切替", "store-phased": "ストア段階配信" })[value];
const coexistenceText = (value: VersionTransition["coexistence"]) => ({ compatible: "新旧共存可能", "feature-flag": "Feature Flagで共存", incompatible: "新旧共存不可" })[value];
function versionTransition(change: ComponentChange, target: Component, release: Release): VersionTransition { const configured = release.componentPlans?.find((plan) => plan.componentId === target.id); if (configured) return configured; if (change.versionTransition) return change.versionTransition; const releaseAt = new Date(release.scheduledAt ?? `${release.scheduledFor}T10:00:00`); const local = (date: Date) => { const shifted = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return shifted.toISOString().slice(0, 16); }; const at = (dayOffset: number, hour: number, minute = 0) => { const date = new Date(releaseAt); date.setDate(date.getDate() + dayOffset); date.setHours(hour, minute, 0, 0); return local(date); }; const revision = change.pullRequests[0]?.revision ?? "未設定"; const versions: Record<ComponentKind, [string, string]> = { ios: ["4.12.0", "4.13.0"], android: ["6.8.1", "6.9.0"], backend: ["prod@61d0f8b", `artifact@${revision}`], admin: ["prod@28ab2d1", `artifact@${revision}`] }; const [currentVersion, targetVersion] = versions[target.kind]; if (target.kind === "ios") { const startsAt = at(0, 10); const expectedCompletionAt = at(7, 10); return { currentVersion, targetVersion, versionSource: "app-store", rollout: "store-phased", startsAt, expectedCompletionAt, coexistence: "feature-flag", adoptionMilestones: rolloutMilestones("store-phased", startsAt, expectedCompletionAt) }; } if (target.kind === "android") { const startsAt = at(0, 11); const expectedCompletionAt = at(5, 11); return { currentVersion, targetVersion, versionSource: "google-play", rollout: "store-phased", startsAt, expectedCompletionAt, coexistence: "feature-flag", adoptionMilestones: rolloutMilestones("store-phased", startsAt, expectedCompletionAt) }; } const startsAt = target.kind === "backend" ? at(-3, 19) : at(-3, 20); const expectedCompletionAt = target.kind === "backend" ? at(-3, 19, 30) : at(-3, 20, 20); return { currentVersion, targetVersion, versionSource: "deployment", rollout: "immediate", startsAt, expectedCompletionAt, coexistence: "compatible", adoptionMilestones: [{ at: expectedCompletionAt, percentage: 100 }] }; }
function rolloutMilestones(rollout: VersionTransition["rollout"], startsAt: string, expectedCompletionAt: string) { const start = new Date(startsAt).getTime(); const end = new Date(expectedCompletionAt).getTime(); const percentages = rollout === "immediate" ? [100] : [10, 25, 50, 100]; return percentages.map((percentage, index) => ({ percentage, at: new Date(start + ((end - start) * index) / Math.max(percentages.length - 1, 1)).toISOString().slice(0, 16) })); }
const dateTimeText = (value: string) => new Intl.DateTimeFormat("ja-JP", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
const shortDateTime = (value: Date) => new Intl.DateTimeFormat("ja-JP", { month: "numeric", day: "numeric" }).format(value);
function timelineRange(transitions: VersionTransition[]) { if (!transitions.length) { const now = Date.now(); return { start: now, end: now + 24 * 60 * 60 * 1000 }; } const starts = transitions.map((item) => new Date(item.startsAt).getTime()); const ends = transitions.map((item) => new Date(item.expectedCompletionAt).getTime()); return { start: Math.min(...starts) - 12 * 60 * 60 * 1000, end: Math.max(...ends) + 12 * 60 * 60 * 1000 }; }
function percentAt(value: string, range: { start: number; end: number }) { return Math.max(0, Math.min(100, ((new Date(value).getTime() - range.start) / (range.end - range.start)) * 100)); }
function releasePlanRisks(data: Store, release: Release, groups: ComponentChangeGroup[]) { const risks: { level: "low" | "medium" | "high"; scope: string; title: string; body: string; control: string }[] = []; const mobile = groups.filter((group) => ["ios", "android"].includes(group.component.kind)); const backend = groups.find((group) => group.component.kind === "backend"); const mobileCompletion = Math.max(...mobile.map((group) => new Date(versionTransition(group.changes[0], group.component, release).expectedCompletionAt).getTime()), 0); mobile.forEach((group) => { const transition = versionTransition(group.changes[0], group.component, release); risks.push({ level: transition.coexistence === "incompatible" ? "high" : "medium", scope: group.component.name, title: "新旧バージョンの同時稼働", body: `${dateTimeText(transition.startsAt)}から${dateTimeText(transition.expectedCompletionAt)}まで旧版利用者が残ります。`, control: transition.coexistence === "feature-flag" ? "新APIはFeature Flagで有効化し、旧APIを維持" : "互換APIとversion別メトリクスを維持" }); }); if (mobile.length) risks.push({ level: "high", scope: "iOS・Android", title: "即時rollback不可", body: "ストア配布後のクライアントバイナリはサーバーのように一括で旧版へ戻せません。", control: "Feature Flagで機能停止し、修正版配布まで旧APIを維持" }); if (backend?.changes.some((change) => change.migration.required)) risks.push({ level: "medium", scope: backend.component.name, title: "contract migrationの実行時期", body: "旧クライアントが参照するschemaを段階配信中に削除できません。", control: mobileCompletion ? `モバイル100%到達後の${dateText(new Date(mobileCompletion + 86400000).toISOString().slice(0, 10))}以降を実行条件に設定` : "依存クライアントの利用終了を実行条件に設定" }); if (mobile.length) risks.push({ level: "medium", scope: "配信監視", title: "到達率は予定値", body: "審査時間と利用者の更新状況により100%到達時刻は変動します。", control: "バージョン別エラー率が2%を超えた場合は配信を停止" }); groups.forEach((group) => group.changes.filter((change) => change.maintenance === "undetermined" || !change.recovery.trim()).forEach((change) => risks.push({ level: "high", scope: group.component.name, title: change.maintenance === "undetermined" ? "停止要否が未判定" : "回復方法が未登録", body: change.summary, control: "実行計画の確定前に担当チームが登録" }))); if (hasCycle(getChanges(release))) risks.push({ level: "high", scope: "コンポーネント間依存", title: "循環依存", body: "依存関係から実行順序を確定できません。", control: "依存を分割するかFeature Flagで有効化順を分離" }); return risks; }
